import subprocess
import os

os.chdir('/Users/dannygomez/.hermes')

# Check what large files are in our current commit
r = subprocess.run(['git', 'ls-tree', '-r', '--long', 'HEAD'], capture_output=True, text=True)
lines = r.stdout.strip().split('\n')

large_in_head = []
for line in lines:
    # Format: <mode> <type> <sha> <size>\t<path>
    if '\t' in line:
        meta, path = line.split('\t', 1)
        parts = meta.split()
        if len(parts) >= 4:
            try:
                size = int(parts[3])
                if size > 50_000_000:
                    large_in_head.append((path, size))
            except ValueError:
                pass

print(f'Found {len(large_in_head)} large files in HEAD:')
for path, size in large_in_head[:30]:
    print(f'  {path}: {size / 1_000_000:.1f} MB')
